#!/usr/bin/env bash
set -euo pipefail

BRANCH="${1:-feature/kosmora-privacy-segmented-acceptance}"
BASE_REF="${2:-origin/main}"

echo "[1/4] Fetching latest refs..."
git fetch origin || true

if git rev-parse --verify "$BASE_REF" >/dev/null 2>&1; then
  git checkout -B "$BRANCH" "$BASE_REF"
elif git rev-parse --verify origin/master >/dev/null 2>&1; then
  git checkout -B "$BRANCH" origin/master
else
  git checkout -B "$BRANCH"
fi

echo "[2/4] Applying Kosmora Privacy Segmented Export & Fence Recovery patch..."
TMP_PATCH="$(mktemp)"
trap 'rm -f "$TMP_PATCH"' EXIT
cat << 'B64EOF' | base64 -d > "$TMP_PATCH"

B64EOF

git apply --check "$TMP_PATCH"
git apply "$TMP_PATCH"

echo "[3/4] Committing changes on $BRANCH..."
git add -A
git commit -m "feat(privacy): implement segmented owner export, full usage/audit inventory, and fence recovery"

echo "[4/4] Pushing $BRANCH to origin..."
git push -u origin "$BRANCH"
echo "Done! Branch $BRANCH is ready for PR."